#include <print>
#include <vector>

int total(const std::vector<int>& v) {
    int sum = 0;
    v[0] = 0;                      // 报错停在赋值这一行：那个位置是只读的
    for (int x : v) sum += x;
    return sum;
}

int main() {
    std::vector<int> scores = {85, 92, 78, 96};
    std::println("总分 = {}", total(scores));
    return 0;
}

